// The day's affirmation in Turkish, for the country pages in Turkish. Written by scripts/home_extras.py from data/affirmations-i18n/; do not edit.
(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"Bugün her şeyi yapmak zorunda değilsin. Sıradaki küçük adım yeter.\", \"Yorgunluk başarısızlık değil. Yorgunsun, çünkü her gün oradasın.\", \"Bulaşıklar bekleyebilir. Beş dakika oturmaya hakkın var.\", \"Akşam yemeğinde mısır gevreği de aileni doyurmak sayılır.\", \"Dinlenmeyi hak etmen gerekmiyor. Şu an dinlenebilirsin.\", \"Bazı günler zafer, herkesin yatma saatine kadar sağ salim gelmesidir. Bu gerçek bir zaferdir.\", \"Kimsenin görmediği kadar çok şey yapıyorsun. Ben görüyorum.\", \"Dağınık bir ev ve sevilen çocuklar. Bu iyi bir takas.\", \"Zor bir günde elinden gelenin en iyisi farklı görünür, ama yine de sayılır.\", \"Derin bir nefes. Omuzlarını bırak. Gayet iyi gidiyorsun.\", \"Bugün çıtayı düşürmek sorun değil. Başka bir gün yine yükseltirsin.\", \"Yardım istemek güçlü olmaktır, zayıflık değil.\", \"Bir şeye daha hayır deme hakkın var.\", \"Bugün kendini yalnız hissettiysen, böyle hisseden tek anne sen değilsin. Biz çok kişiyiz.\", \"Sana nasıl olduğunu soran ve cevabını bekleyen bir arkadaşı hak ediyorsun.\", \"İlk adımı senin atman sorun değil. Çoğu anne birinin atmasını umuyor.\", \"Görülmediğini hissetmek önemsiz olduğun anlamına gelmez. Çok önemlisin.\", \"Hissettiklerin anlamlı. Sen fazla değilsin.\", \"Burada zor gününü açıklamak zorunda değilsin. Anlıyoruz.\", \"Başka bir anneye “ben de” diyen bir mesaj, bütün bir günü değiştirebilir.\", \"Beslemek, alt değiştirmek, sallamak ve yeniden. Bu, oturuyor gibi görünse de gerçek bir emek.\", \"Sen ve bebeğin hâlâ birbirinizi tanıyorsunuz. Acele yok.\", \"Yenidoğanla geçen günler uzun. Bu dönem sonsuza kadar sürmeyecek.\", \"Bugün tek yaptığın küçücük bir insanı tok ve sıcak tutmaksa, çok büyük bir iş yaptın.\", \"Hemen eski hâline dönmek zorunda değilsin. Olduğun yerde olabilirsin.\", \"Bebeğin nasıl beslenirse beslensin, ona sen bakıyorsun. Önemli olan bu.\", \"Hem uykusuz hem de sevgi dolu olabilirsin.\", \"Bebeği kucakla, evi boş ver. Ev yine orada olacak.\", \"Markette bir kriz seni kötü bir anne yapmaz. Sadece küçük bir çocuğun olduğu anlamına gelir.\", \"Küçükler sınırları zorlar, çünkü yanında kendilerini güvende hissederler.\", \"Bugün dünden bir dakika daha uzun sakin kaldın. Bu da sayılır.\", \"Sinirlendiysen, bir sarılma ve bir “özür dilerim” çok şeyi düzeltir. Üstelik onlara güzel bir şey de öğretir.\", \"Yapış yapış eller, yüksek sesler, kocaman duygular. Bir insanı bütünüyle yetiştiriyorsun.\", \"Bu saatteki beşinci “neden?”, büyüyen küçük bir zihin.\", \"Mutlu bir anı için kusursuz bir güne ihtiyacın yok.\", \"Çarpılan bir kapı hikâyenin sonu değil. Işığı açık bırak.\", \"Ergen çocuğun söylemeyebilir ama hep yanında olman çok önemli.\", \"Evdeki sakin kişi olmak zor bir iş. Ve sen bunu yapıyorsun.\", \"En güzel sohbetlerin bazıları arabada olur. Sen sürmeye devam et.\", \"Büyümek için uzaklaşıyorlar, seni geride bırakmak için değil.\", \"Her sorunun cevabını bilmek zorunda değilsin. Dinlemek işin büyük kısmı.\", \"Büyük çocukların hâlâ sana ihtiyacı var, sadece daha sessizce.\", \"Her şeyi tek başına göğüslemek, çoğu insanın hiç görmediği bir güç ister.\", \"Çocuğun için yeterince iyi bir annesin. Hep öyleydin.\", \"Bir çift el, yüz iş. Kendine nazik davran.\", \"Çocukların seni izleyerek güçlü ve sevgi dolu bir insanın nasıl olduğunu öğreniyor.\", \"Mola vermek görevi bırakmak değil. Devam edebilmenin yolu bu.\", \"Kimse puan tutmuyor. Önemli olan sevgi ve yanlarında olmak.\", \"Yas ve sevgi aynı yerden gelir. Birini özlemek, onu ne kadar sevdiğini gösterir.\", \"Yasın doğru bir takvimi yok. İhtiyacın olan zamanı kendine tanı.\", \"Zor yıl dönümlerinde, bir arkadaşına nasıl şefkat gösterirsen kendine de öyle göster.\", \"Hem hüzün taşıyıp hem çocuklarınla gülebilirsin. İkisi de gerçek.\", \"Bir gebeliği ya da bir bebeği kaybettiysen, o kayıp gerçek; sevgin de öyle.\", \"Bazı günler yas sessizdir, bazı günler gürültülü. İkisi de olur.\", \"Az para, az sevgi demek değil.\", \"Çocukların, aldığın şeylerden çok seninle geçen zamanı hatırlayacak.\", \"Faturalar için yardım sormak akıllıca, utanılacak bir şey değil. O yardım tam da bunun için var.\", \"Parkta bedava bir öğleden sonra haftanın en güzel günü olabilir.\", \"Parayı bir hafta daha yetirdin. Bu gerçek bir beceri ister.\", \"Para derdi yorar. Çok şey taşıyorsun ve hâlâ buradasın.\", \"Bugün bir bardak su içtin. Oradan başla.\", \"Herkes kapıdan çıktı. Ayakkabılar belki uyumsuzdu. Yine de bir zafer.\", \"Korktuğun o telefonu açtın. Cesaret istiyordu.\", \"Bugün güldün. Buna sıkı tutun.\", \"Sıcak bir yemek, temiz bir tişört, bir masal. Küçük şeyler bir araya gelip bir çocukluk olur.\", \"Bugün birine nazik davrandın, o kişi sadece sen olsan bile.\", \"Kusursuzluk değil, ilerleme. Bugün bir adım ileri gittin.\", \"Listeden bir şeyi bitirdin. Hiç yoktan bir fazla.\", \"Sen iyi bir annesin. Bunu dert etmen, ne kadar önemsediğini gösteriyor.\", \"Bir günde yetiştirebildiklerinden çok daha fazlasısın.\", \"Çocuklarının kusursuz bir anneye ihtiyacı yok. Sana ihtiyaçları var ve seni yanlarında buluyorlar.\", \"Çocuklarına gösterdiğin sabrı kendine de göster.\", \"Yer kaplamaya, bir şeyler istemeye ve kendi hayallerine sahip olmaya hakkın var.\", \"Bir hata sevgiyi silmez. Yarın yeni bir başlangıç.\", \"Birinin bütün dünyasısın, ama aynı zamanda kendine ait bir insansın.\", \"Her dakikayı sevmemen normal. Yine de çocuklarını bütün kalbinle sevebilirsin.\", \"Anne olmanın tek bir doğru yolu yok. Senin yolun da geçerli.\", \"Ağaç duruşundaki gibi sallanmak sorun değil. Dengeni yeniden bulabilirsin.\", \"Ayaklarını dağ duruşundaki gibi yere bas. Hissettiğinden daha sağlamsın.\", \"Savaşçı iki: güçlü bacaklar, açık kollar. İşte bu haftaya göğüs geren sensin.\", \"Dörde kadar nefes al, dörde kadar ver. Buradasın ve gayet iyi gidiyorsun.\", \"Bir yıldız gibi geniş geniş uzan. Yer kaplamaya hakkın var.\", \"Geniş ve alçak bir çömelme zor tutulur. Uzun bir gün de öyle. Sen tutuyorsun.\", \"Bir hilal gibi eğilip yine de ayakta kalabilirsin.\", \"Ayak parmaklarına henüz uzanmak zorunda değilsin. Her küçük esneme sayılır.\", \"Üçgen duruşu: bir el aşağıda, bir el yukarıda. Yere sağlam bas ve uzanmaya devam et.\", \"Saat geç oldu. Bugün yapılamayanlar yarını bekleyebilir.\", \"Bu saatte bebekle uyanık mısın? Şu an seninle birlikte uyanık bir sürü anne var.\", \"Ev sessiz. Bu an senin. Nefes al.\", \"Bugünü atlattın. Bugünün ihtiyacı sadece buydu.\", \"Bu gece aklın durmuyorsa, yaz onları ve sabaha kadar beklesinler.\", \"Gözlerini dinlendir. Yarın yeniden başlayabilirsin.\", \"Bayramlar ve tatiller mutlu olduğu kadar zor da olabilir. Bu dönem sana nasıl geliyorsa, sorun değil.\", \"Sofranın kusursuz olması gerekmiyor. Önemli olan etrafındaki insanlar.\", \"Bu yıl sofrada birinin eksikliğini hissediyorsan, kalbine nazik davran.\", \"Teşekkürler anne, her yemek, her yolculuk ve her sarılma için.\", \"Misafir ağırlamak, pasta yapmak ya da hep gülümsemek zorunda değilsin. Sade bir kutlama da kutlamadır.\", \"Çocuklarının bu yıl alacağı en güzel hediye, seninle geçirdikleri zaman.\", \"Küçük bir kutlama da sevgi doludur. Özel olması için çok para gerekmez.\", \"Soğuk günler, sıcak sarılmalar. Evinin sıcak köşesi sensin.\", \"Yoğun koşturmacanın bir kısmını atlamak sorun değil. Huzur da bir hediyedir.\", \"Bu dönem bu yıl sana ağır geliyorsa, yalnız değilsin. Her seferinde tek bir gün.\"]";D.body.appendChild(e)})();
